import json
import shutil
from pathlib import Path

import pytest
import yaml
from conftest import _load, workflow_step

REPO = Path(__file__).resolve().parents[3]


@pytest.fixture(scope="session")
def ns():
    return _load("new_skill")


@pytest.fixture
def repo(tmp_path):
    """A copy of this repository's sources, without generated caches."""
    for name in ("LICENSE", ".claude-plugin", "docs", "plugins", "community-plugins"):
        src = REPO / name
        (shutil.copytree if src.is_dir() else shutil.copyfile)(src, tmp_path / name)
    for name in (".agents", ".cursor-plugin"):
        shutil.copytree(REPO / name, tmp_path / name)
    return tmp_path


def run(ns, root, *args):
    return ns.main([*args, "--root", str(root)])


def test_repository_has_no_placeholders(ns):
    assert run(ns, REPO, "--check") == 0


def test_new_plugin_is_registered_and_gated(ns, repo, capsys):
    assert run(ns, repo, "gaia-test-plugin", "picking-signals", "--maintainer", "@someone",
               "--agent", "signal-picker") == 0
    pdir = repo / "community-plugins/gaia-test-plugin"
    assert (pdir / "skills/picking-signals/SKILL.md").is_file()
    assert (pdir / ".claude-plugin/plugin.json").is_file()  # generated by the sync step
    assert (pdir / "LICENSE").read_text() == (repo / "LICENSE").read_text()
    agent = (pdir / "agents/signal-picker.md").read_text()
    assert yaml.safe_load(agent.split("---")[1])["skills"] == ["picking-signals"]
    entries = json.loads((repo / ".claude-plugin/marketplace.json").read_text())["plugins"]
    assert {"name": "gaia-test-plugin", "source": "./community-plugins/gaia-test-plugin",
            "category": "community", "strict": False}.items() <= next(
        e for e in entries if e["name"] == "gaia-test-plugin").items()
    meta = yaml.safe_load((repo / "docs/catalog.yml").read_text())["plugins"]["gaia-test-plugin"]
    assert meta["tier"] == "Community" and meta["maintainer"] == "@someone"
    assert "picking-signals" in meta["skills"]
    assert "gaia-test-plugin" in (repo / "docs/catalog.md").read_text()
    capsys.readouterr()
    assert run(ns, repo, "--check") == 1
    assert "TODO(scaffold)" in capsys.readouterr().out


def test_skill_added_to_existing_plugin_keeps_comments(ns, repo):
    before = (repo / "docs/catalog.yml").read_text()
    assert run(ns, repo, "gaia-core", "second-skill", "--no-sync") == 0
    after = (repo / "docs/catalog.yml").read_text()
    assert after.startswith(before.split("plugins:")[0])  # header comments untouched
    skills = yaml.safe_load(after)["plugins"]["gaia-core"]["skills"]
    assert set(skills) == {"authoring-gaia-skills", "second-skill"}
    assert (repo / "plugins/gaia-core/skills/second-skill/SKILL.md").is_file()


def test_new_plugin_requires_maintainer(ns, repo):
    with pytest.raises(SystemExit, match="maintainer"):
        run(ns, repo, "gaia-orphan", "some-skill")


def test_rejects_bad_names_and_existing_skill(ns, repo):
    with pytest.raises(SystemExit, match="lowercase"):
        run(ns, repo, "Bad_Name", "x-skill", "--maintainer", "@a")
    with pytest.raises(SystemExit, match="already exists"):
        run(ns, repo, "gaia-core", "authoring-gaia-skills", "--no-sync")


def test_workflow_runs_scaffold_check():
    assert "pixi run scaffold-check" in workflow_step("validate-plugins.yml", "Check no scaffold placeholders remain")
